            ["SearchPage_InvalidScope"] = ("Enter a full folder path, such as D:\\Projects.", "搜索范围需要完整的文件夹路径，例如 D:\\资料。", "検索範囲には D:\\Projects のような完全なフォルダーパスを入力してください。"),
