            ["SearchDiskUsage"] = ("Index disk usage", "索引磁盘占用", "インデックスのディスク使用量"),
            ["SearchDiskUsageHint"] = ("Includes database logs and temporary files used by an active rebuild.", "包含数据库日志和本次重建的临时文件。", "データベースのログと再構築中の一時ファイルを含みます。"),
