            ["SearchSizeUnavailable"] = ("Unavailable", "暂时无法读取", "取得できません"),
            ["SearchRelocating"] = ("Moving the index… Search will use the new location after verification.", "正在迁移索引… 校验完成后切换到新位置。", "インデックスを移動中… 検証後に新しい場所へ切り替えます。"),
            ["SearchRelocated"] = ("Index moved. Search now uses the new location.", "索引已迁移，搜索已使用新位置。", "インデックスを移動しました。検索は新しい場所を使用します。"),
            ["SearchRelocatedRetained"] = ("Index moved. The old copy could not be safely removed and is still at: {0}", "索引已迁移。旧副本暂时无法安全清理，仍保留在：{0}", "インデックスを移動しました。安全に削除できなかった旧コピーが残っています：{0}"),
            ["SearchOperationFailed"] = ("Could not complete the operation: {0}", "操作未完成：{0}", "操作を完了できませんでした：{0}"),
            ["SearchIndexCancelled"] = ("Indexing cancelled. The previous index is still available.", "已取消索引，本次重建未替换原索引。", "インデックス作成を中止しました。以前のインデックスは保持されています。"),
            ["Backup_LocationUnavailable"] = ("This backup location is no longer available. Refresh the backup list or reconnect its drive.", "这个备份位置暂时不可用，请刷新备份列表或重新连接所在磁盘。", "このバックアップの場所は利用できません。一覧を更新するか、ドライブを再接続してください。"),
            ["UseBundledFileIcons"] = ("Use FilesMate file icons", "使用 FilesMate 文件图标", "FilesMate のファイルアイコンを使用"),
            ["UseBundledFileIconsHint"] = ("On by default. Turn off to use Windows icons for the associated apps. Applies immediately; image and video thumbnails are preserved.", "默认开启。关闭后使用 Windows 文件关联图标，显示默认打开软件对应的图标。立即生效，保留图片和视频缩略图。", "既定でオンです。オフにすると、Windows で関連付けられたアプリのアイコンを使います。すぐに反映され、画像と動画のサムネイルは保持します。"),
            ["Backup_Title"] = ("Replacement backups and undo", "替换备份与撤销", "置換バックアップと元に戻す"),
            ["Backup_SettingsHint"] = ("Keep the overwritten version within the backup limits for Undo. Ordinary deletion uses the Windows Recycle Bin and does not create another copy.", "覆盖同名文件时，在备份额度内保留旧版本用于撤销。普通删除使用系统回收站，不创建额外副本。", "同名ファイルの上書き時、上限内で旧版を保存して元に戻せます。通常の削除はWindowsのごみ箱を使い、追加のコピーは作成しません。"),
            ["Backup_DeletePolicy"] = ("Deleting a folder sends the entire item to the Windows Recycle Bin; the 256 MiB replacement-backup limit does not apply. Permanent deletion keeps no copy. Windows warns if an item cannot be recycled.", "普通删除文件夹时，整个项目移入系统回收站，不受 256 MiB 替换备份额度限制。永久删除不保留副本；无法移入回收站时，Windows 会提示。", "フォルダーの通常削除では全体をごみ箱へ移動し、置換バックアップの256 MiB制限は適用しません。完全削除ではコピーを残しません。ごみ箱へ移動できない場合はWindowsが警告します。"),
            ["Backup_Manage"] = ("Manage backups", "管理备份", "バックアップを管理"),
            ["Backup_Policy"] = ("Keep up to 5 operations in this session. Replacement backups reserve at most 256 MiB in total and 64 MiB per file (up to 256 files). Space is reserved for the larger of the old and new versions. Backups are cleared when the last window closes normally.", "当前会话最多保留 5 次操作。替换备份合计最多预留 256 MiB、单个文件最多 64 MiB（最多 256 个文件），按新旧版本中较大的一个预留。正常关闭最后一个窗口时清理。", "このセッションで最大5操作を保持します。置換バックアップの予約容量は合計256 MiB、1ファイル64 MiB（最大256ファイル）です。新旧の大きい方のサイズを予約し、最後のウィンドウを正常に閉じると削除します。"),
            ["Backup_Usage"] = ("Reserved for undo/redo: {0} / 256 MiB · {1} backup locations", "撤销/重做预留：{0} / 256 MiB · {1} 个备份位置", "元に戻す/やり直し用の予約：{0} / 256 MiB · {1}か所"),
            ["Backup_ReservationHint"] = ("Undo reserves {0} MiB on the destination drive (currently {1} / 256 MiB). Up to 5 operations are retained. Manage or clear backups in Settings → Files & folders.", "撤销将在目标磁盘预留 {0} MiB（当前 {1} / 256 MiB），最多保留 5 次操作。可在设置 → 文件与文件夹中查看和清理。", "転送先ドライブに{0} MiBを予約します（現在{1} / 256 MiB）。最大5操作を保持します。設定 → ファイルとフォルダーで管理・削除できます。"),
            ["Backup_LimitHint"] = ("Undo would reserve {0} MiB (currently {1} / 256 MiB). The backup limit has been reached, or backups are unavailable. Skip, keep both, cancel and manage backups, or explicitly replace without undo.", "撤销需要预留 {0} MiB（当前 {1} / 256 MiB），已超过备份限制或备份不可用。可以跳过、保留两者、取消后管理备份，或明确选择不可撤销的替换。", "{0} MiBの予約が必要です（現在{1} / 256 MiB）。上限に達したか、バックアップを利用できません。スキップ、両方を保持、キャンセルして管理、または元に戻せない置換を選択してください。"),
            ["Backup_ReplaceWithoutUndo"] = ("Replace without undo", "替换且无法撤销", "元に戻せない置換"),
            ["Backup_DestructiveHint"] = ("The existing contents will be permanently replaced without retaining an old version. This entire batch cannot be undone, and previous undo/redo history will be cleared after a replacement succeeds. Select the remaining-conflicts option to apply this choice to other conflicts of the same kind in this operation.", "已有内容将被永久替换，不保留旧版本。本次操作无法撤销；替换成功后，也会清除之前的撤销/重做历史。勾选剩余冲突选项后，同一操作中的其他同类冲突也会使用这个选择。", "旧バージョンを残さず、既存の内容を完全に置き換えます。今回の操作は元に戻せず、置換に成功すると以前の元に戻す/やり直し履歴も消去されます。残りの競合に適用する項目を選ぶと、今回の操作の同種の競合にもこの選択を適用します。"),
            ["Backup_UnprotectedCount"] = ("{0} replaced without backup; this batch cannot be undone", "{0} 项未保留备份，本次操作无法撤销", "{0}件をバックアップなしで置換。今回の操作は元に戻せません"),
            ["Backup_Clear"] = ("Clear current undo history", "清除当前撤销历史", "現在の履歴を消去"),
            ["Backup_ClearHint"] = ("Clearing history permanently removes its backup versions and disables Undo/Redo. Recovery copies from interrupted sessions or changed backups are kept: open a location below to inspect and recover them before deleting them yourself. Older unregistered folders are not deleted by name.", "清除历史会永久删除其备份版本，不能再撤销/重做。异常退出残留或已被修改的备份会保留：点击下方位置检查、恢复所需文件后，可自行删除。旧版本未登记的目录不会仅凭名称自动删除。", "履歴を消去すると、そのバックアップは完全に削除され、元に戻す/やり直しはできなくなります。異常終了時や変更されたバックアップは保持します。下の場所を開き、必要なファイルを復元してから手動で削除してください。旧版の未登録フォルダーは名前だけで自動削除しません。"),
            ["Backup_Cleared"] = ("Current history cleared. Any remaining locations need inspection; their files were not deleted.", "当前历史已清除。仍列出的位置需要检查，其中的文件未被删除。", "現在の履歴を消去しました。残っている場所は確認が必要で、ファイルは削除していません。"),
            ["Backup_Remnants"] = ("Undo backups from an earlier session are still on disk", "磁盘上仍有之前会话留下的撤销备份", "以前のセッションのバックアップが残っています"),
            ["Transfer_InvalidDestination"] = ("The destination is this item, its current parent, or a subfolder of it. Choose another destination.", "目标是项目自身、当前所在文件夹或其子文件夹，请选择其他位置。", "転送先は項目自身、現在の親フォルダー、または子フォルダーです。別の場所を選択してください。"),
